using System.Collections;
using UnityEngine;
namespace CoopBeam {
public class IceKingBoss:MonoBehaviour {
 public Collider2D core;public SpriteRenderer coreArt;public int Phase{get;private set;}=1;public bool Vulnerable{get;private set;}public bool Telegraphing{get;private set;}public bool Attacking{get;private set;}public bool Defeated{get;private set;}public float DefeatAge=>Defeated?Time.time-defeatedAt:0;public string Hint{get;private set;}="EL REY DESPIERTA";public int PatternsCompleted{get;private set;}public int Transformations{get;private set;}
 EnemyBase enemy;Rigidbody2D body;int sequence,target;float defeatedAt;bool transforming;const float First=.68f,Second=.34f;
 void Awake(){enemy=GetComponent<EnemyBase>();body=GetComponent<Rigidbody2D>();enemy.externalControl=true;}
 IEnumerator Start(){yield return new WaitUntil(()=>GameManager.Instance&&GameManager.Instance.Running);while(!Defeated){int desired=enemy.Health<=enemy.maxHealth*Second+.01f?3:enemy.Health<=enemy.maxHealth*First+.01f?2:1;if(desired>Phase){yield return Transform(desired);continue;}yield return Pattern();}}
 public float FilterDamage(float amount,float health){if(!Vulnerable||Defeated||transforming)return 0;float floor=Phase==1?enemy.maxHealth*First:Phase==2?enemy.maxHealth*Second:0;return Mathf.Min(amount,Mathf.Max(0,health-floor));}
 IEnumerator Transform(int phase){transforming=true;Vulnerable=Attacking=Telegraphing=false;core.enabled=false;EncounterHazard.ClearOwned(this);Hint="LA CORONA SE FRACTURA / CAMBIEN DE ALTURA";for(float t=0;t<2.5f;t+=.15f){if(!GameManager.Instance.Running)yield break;BeamFX.Burst(transform.position,phase==3?new Color(.8f,.4f,1):Color.cyan,7);yield return new WaitForSeconds(.15f);}Phase=phase;Transformations++;transforming=false;sequence=0;}
 IEnumerator Pattern(){Vulnerable=false;core.enabled=false;target=1-target;var game=GameManager.Instance;if(!game.Running)yield break;if(game.players[target].Dead)target=1-target;Vector2 aim=game.players[target].transform.position;int pattern=sequence++%4;Telegraphing=true;enemy.combatTelegraph=true;
  Hint=pattern==0?"AGUJAS REALES / MUEVANSE TRAS EL AVISO":pattern==1?"AVALANCHA / BUSQUEN EL HUECO AMBAR":pattern==2?"ANILLOS DE ESCARCHA / SALTEN LAS ONDAS":"COLUMNAS DE CRISTAL / CAMBIEN DE CARRIL";
  Vector2 launch=(Vector2)transform.position+Vector2.up*1.2f;float gap=Phase==3?(target==0?-4:4):Mathf.Clamp(aim.x,-7,7);if(pattern==1)for(int i=-9;i<=9;i+=3)if(Mathf.Abs(i-gap)>2.1f)EncounterHazard.Spawn(new Vector2(i,4.9f),new Vector2(.55f,1.1f),1.2f,2,new Vector2(0,-5.7f),Color.cyan,this,true);
  if(pattern==3)for(int i=0;i<(Phase==1?2:3);i++){float x=Mathf.Clamp(aim.x+(i-1)*3.5f,-9,9);EncounterHazard.Spawn(new Vector2(x,-2.6f),new Vector2(1.05f,3.1f),1.25f,1.1f,Vector2.zero,Color.cyan,this);}
  yield return new WaitForSeconds(1.15f);if(!game.Running||Defeated)yield break;Telegraphing=enemy.combatTelegraph=false;Attacking=true;
  if(pattern==0){Vector2 direction=(aim-launch).normalized;int n=Phase+2;for(int i=0;i<n;i++){float angle=(i-(n-1)*.5f)*19;Vector2 d=Quaternion.Euler(0,0,angle)*direction;EncounterHazard.Spawn(launch+d*.6f,Vector2.one*.45f,.08f,3,d*(Phase==3?5.5f:4.5f),new Color(.65f,.9f,1),this,true);}}
  if(pattern==2)for(int s=-1;s<=1;s+=2){EncounterHazard.Spawn(new Vector2(0,-3.9f),new Vector2(.65f,.65f),.15f,2,new Vector2(s*5.5f,0),Color.cyan,this,true);if(Phase>=2)EncounterHazard.Spawn(new Vector2(0,.85f),new Vector2(.65f,.5f),.8f,2,new Vector2(s*4,0),new Color(.8f,.5f,1),this,true);}
  yield return new WaitForSeconds(Phase==3?2.4f:2.8f);if(!game.Running||Defeated)yield break;Attacking=false;EncounterHazard.ClearOwned(this);Vulnerable=true;core.enabled=true;core.transform.localPosition=new Vector3(0,Phase==2?1.2f:.3f,0);coreArt.transform.localPosition=core.transform.localPosition;Hint=Phase==2?"NUCLEO ALTO / UNO ARRIBA, OTRO ABAJO":"NUCLEO ABIERTO / RODEEN AL REY";yield return new WaitForSeconds(Phase==3?3.4f:3);Vulnerable=false;core.enabled=false;PatternsCompleted++;
 }
 void Update(){if(coreArt){coreArt.color=Vulnerable?new Color(.5f,1,.85f):new Color(.3f,.65f,.9f,.3f);coreArt.transform.localScale=Vector3.one*(Vulnerable?1+Mathf.Sin(Time.time*7)*.08f:.75f);}if(GameManager.Instance&&!GameManager.Instance.Running&&!Defeated){StopAllCoroutines();Vulnerable=false;if(core)core.enabled=false;EncounterHazard.ClearOwned(this);}}
 public void Defeat(){if(Defeated)return;Defeated=true;defeatedAt=Time.time;Vulnerable=Attacking=Telegraphing=false;StopAllCoroutines();core.enabled=false;foreach(var c in GetComponentsInChildren<Collider2D>())c.enabled=false;EncounterHazard.ClearOwned(this);StartCoroutine(Fall());}
 IEnumerator Fall(){Hint="LA AURORA ES LIBRE";for(int i=0;i<12;i++){BeamFX.Burst(transform.position+(Vector3)Random.insideUnitCircle*1.5f,i%2==0?Color.cyan:Color.white,8);yield return new WaitForSeconds(.14f);}enemy.FinishDeath();}
 void OnDisable(){EncounterHazard.ClearOwned(this);}
 void OnGUI(){if(!GameManager.Instance||!GameManager.Instance.Running)return;GUI.depth=-1;PixelFont.Begin();PixelFont.Panel(new Rect(115,77,410,38),PixelFont.Ink,Color.cyan);PixelFont.Fill(new Rect(125,85,390,5),new Color(.2f,.2f,.35f));PixelFont.Fill(new Rect(125,85,390*Mathf.Clamp01(enemy.Health/enemy.maxHealth),5),Color.cyan);PixelFont.Text(320,94,"REY CENCELLON / FASE "+Phase,1,PixelFont.Cream,true);PixelFont.Text(320,105,Hint,1,PixelFont.Mint,true);}
}
}
